// ===== vostd contract shape models =====
// Frozen source: /tmp/vostd-43da079-ktest-chan/ostd/src (rev 43da0797bbfa)
// `may_panic` is uninterpreted in the frozen source as well:
//   verified_libs/vstd_extra/src/panic.rs:11  `pub uninterp spec fn may_panic() -> bool;`
pub uninterp spec fn may_panic() -> bool;

// sync/mutex.rs MutexGuard::new (lines 217-228) shape: the contract's only
// requires is `perm.id() == mutex.cell_id()` over a Tracked<PointsTo<T>>;
// tracked resources are abstracted to usize ids, equality kept.
pub open spec fn perm_matches_cell(perm_id: usize, mutex_id: usize) -> bool {
    perm_id == mutex_id
}

// sync/mutex.rs Mutex::new (lines 53-64) shape: constructor accepts any
// value; modeled as a non-trivial contingent value domain so the probes
// stay meaningful (a definitionally-true body would verify both probes).
pub open spec fn val_in_domain(val_id: usize) -> bool {
    val_id < 8
}

// Generic arithmetic controls.
pub open spec fn i_lt_len(i: usize, len: usize) -> bool {
    i < len
}
pub open spec fn i_ge_len(i: usize, len: usize) -> bool {
    i >= len
}

// mm/vm_space.rs shapes (lines 566-589 query, 670-688 jump, 909-930 map):
// tracked ghost resources (CursorOwner / MetaRegionOwners / Guards /
// EntryOwner / TlbModel) are abstracted to opaque ids; their invariant
// predicates are uninterpreted — the frozen definitions involve deep
// ghost state (page table views, RCU owners) not reproduced here.
pub uninterp spec fn cursor_invariants(owner: usize, regions: usize, guards: usize) -> bool;
pub uninterp spec fn query_panic_cond(space: usize, owner: usize, regions: usize) -> bool;
pub uninterp spec fn jump_panic_cond(va: usize) -> bool;
pub uninterp spec fn map_panic_cond(frame: usize, prop: usize) -> bool;
pub uninterp spec fn tlb_inv(tlb: usize) -> bool;
pub uninterp spec fn item_wf(frame: usize, prop: usize, entry_owner: usize, regions: usize) -> bool;

pub open spec fn query_requires(space: usize, owner: usize, regions: usize, guards: usize) -> bool {
    cursor_invariants(owner, regions, guards)
        && (query_panic_cond(space, owner, regions) ==> may_panic())
}

pub open spec fn jump_requires(space: usize, va: usize, owner: usize, regions: usize, guards: usize) -> bool {
    cursor_invariants(owner, regions, guards)
        && (jump_panic_cond(va) ==> may_panic())
}

pub open spec fn map_requires(space: usize, frame: usize, prop: usize, owner: usize, entry_owner: usize, regions: usize, guards: usize, tlb: usize) -> bool {
    tlb_inv(tlb)
        && cursor_invariants(owner, regions, guards)
        && item_wf(frame, prop, entry_owner, regions)
        && (map_panic_cond(frame, prop) ==> may_panic())
}
